<div class="seom-panel"><div class="seom-actions"><h2>Site SEO Audit</h2><div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:inline"><input type="hidden" name="action" value="seom_run_audit"><?php wp_nonce_field('seom_run_audit'); ?><button class="button button-primary">Run Full Audit</button></form> <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:inline"><input type="hidden" name="action" value="seom_clear_audit"><?php wp_nonce_field('seom_clear_audit'); ?><button class="button">Clear Results</button></form></div></div><?php $rows=SEO_Manager_Audit::latest();if(!$rows): ?><p>No audit results yet. Run the audit to scan titles, descriptions, headings, links and image ALT coverage.</p><?php else: ?><table class="widefat striped"><thead><tr><th>Severity</th><th>Issue</th><th>URL</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><span class="seom-badge <?php echo esc_attr($r->severity==='critical'?'bad':'warn'); ?>"><?php echo esc_html(strtoupper($r->severity)); ?></span></td><td><?php echo esc_html($r->message); ?></td><td><a href="<?php echo esc_url($r->url); ?>" target="_blank" rel="noopener"><?php echo esc_html($r->url); ?></a></td><td><?php if($r->object_id): ?><a class="button button-small" href="<?php echo esc_url(get_edit_post_link((int)$r->object_id)); ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
